<?php $errors=\App\Core\Session::get('errors',[]);$old=\App\Core\Session::get('old',[]);\App\Core\Session::forget('errors');\App\Core\Session::forget('old');$v=array_merge($record,$old);$edit=$mode==='edit';$selected=json_decode((string)($v['permissions']??'{}'),true)?:[];?>
<div class="page-header"><div><span class="staff-eyebrow">Roles & Permissions</span><h2><?=htmlspecialchars($title)?></h2><p>View permits read-only access. Manage permits creating, editing and other changes.</p></div><a class="btn" href="<?=htmlspecialchars(url('/admin/roles'))?>">Back</a></div>
<form method="post" action="<?=htmlspecialchars(url($edit?'/admin/roles/'.$record['id'].'/update':'/admin/roles/store'))?>"><?=csrf_field()?><section class="card staff-form-section"><div class="staff-form-grid"><div class="form-group"><label>Role Name *</label><input class="form-control" name="name" value="<?=htmlspecialchars((string)($v['name']??''))?>"><?php if(isset($errors['name'][0])):?><span class="invalid-feedback d-block"><?=htmlspecialchars($errors['name'][0])?></span><?php endif?></div><div class="form-group"><label>Slug</label><input class="form-control" name="slug" value="<?=htmlspecialchars((string)($v['slug']??''))?>" placeholder="Generated from name"><?php if(isset($errors['slug'][0])):?><span class="invalid-feedback d-block"><?=htmlspecialchars($errors['slug'][0])?></span><?php endif?></div><div class="form-group span-2"><label>Description</label><textarea class="form-control" name="description" rows="3"><?=htmlspecialchars((string)($v['description']??''))?></textarea></div></div><div class="staff-section-title role-heading"><i data-lucide="blocks"></i><div><h3>Module permissions</h3></div></div><div class="role-permission-grid"><?php foreach($permissionModules as$module=>$label):$actions=$selected[$module]??[];$level=in_array('manage',$actions,true)?'manage':(in_array('view',$actions,true)?'view':'none');?><div><strong><?=htmlspecialchars($label)?></strong><select class="form-control" name="permissions[<?=$module?>]"><option value="none" <?=$level==='none'?'selected':''?>>No Access</option><option value="view" <?=$level==='view'?'selected':''?>>View Only</option><option value="manage" <?=$level==='manage'?'selected':''?>>View & Manage</option></select></div><?php endforeach?></div><button class="btn btn-primary" type="submit"><?=$edit?'Update Role':'Create Role'?></button></section></form>
